from itertools import product

def is_valid(pattern):
    # Rule 1: No two adjacent tiles may be the same color
    for i in range(len(pattern) - 1):
        if pattern[i] == pattern[i + 1]:
            return False
    # Rule 2: Red (R) tiles must always be placed on an even position (positions 1 to 4)
    # Even positions are 2 and 4 (1-indexed), which correspond to indices 1 and 3 (0-indexed)
    for i, c in enumerate(pattern):
        if c == 'R' and (i + 1) % 2 != 0:
            return False
    return True

