from itertools import combinations

def count_changes(path):
    changes = 0
    for i in range(1, len(path)):
        if path[i] != path[i-1]:
            changes += 1
    return changes

def valid_prefix(path):
    d = 0
    r = 0
    for c in path:
        if c == 'D':
            d += 1
        else:
            r += 1
        if d < r:
            return False
    return True

