from itertools import product

def main():
    grid_size = 3
    blocked = (2, 2)
    start = (1, 1)
    end = (3, 3)

    paths = []

    # Generate all paths of length 4 (2 R's and 2 D's)
    for moves in product('RD', repeat=4):
        if moves.count('R') != 2 or moves.count('D') != 2:
            continue
        path_str = ''.join(moves)
        # Simulate path
        r, c = start
        valid = True
        diag_count = 0
        # Check start
        if r == c:
            diag_count += 1
        for move in moves:
            if move == 'R':
                c += 1
            else:
                r += 1
            if (r, c) == blocked:
                valid = False
                break
            if r == c:
                diag_count += 1
        if valid and (r, c) == end:
            paths.append((path_str, diag_count))

    # Sort lexicographically ('D' < 'R')
    paths.sort(key=lambda x: x[0])

    total = len(paths)
    two_diag = sum(1 for p, d in paths if d == 2)

    print(f"Total Paths: {total}")
    for p, d in paths:
        print(p)
    print(f"Visit Two Diagonal Cells: {two_diag}")

if __name__ == "__main__":
    main()

